package com.soundtracker;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.Clipboard;
import java.awt.datatransfer.StringSelection;
import java.util.stream.Stream;

public class SoundTrackerPanel extends PluginPanel
{
    private final JLabel currentSoundLabel = new JLabel("ID (0/0) : -");
    private final JLabel channelLabel = new JLabel("Channel: -");

    private final JButton startTrackingButton = new JButton("Start");
    private final JButton stopTrackingButton = new JButton("Stop");
    private final JButton playPreviousButton = new JButton("<<");
    private final JButton playCurrentButton = new JButton("↻");
    private final JButton playNextButton = new JButton(">>");
    private final JButton saveSoundButton = new JButton("Save");
    private final JButton removeSoundButton = new JButton("Remove");
    private final JButton exportSavedButton = new JButton("Export to clipboard");
    private final JButton clearTrackedButton = new JButton("Clear tracked sounds");
    private final JButton clearRemovedButton = new JButton("Clear removed sounds");
    private final JButton clearSavedButton = new JButton("Clear saved sounds");
    private final JLabel soundExportLabel = new JLabel("Sound export");
    private final JLabel trackerTitleLabel = new JLabel("Sound Tracker");
    private final JCheckBox trackAreaCheckbox = new JCheckBox("Area", true);
    private final JCheckBox trackLocalCheckbox = new JCheckBox("Local", true);
    private final JCheckBox includeAreaCheckbox = new JCheckBox("Area", true);
    private final JCheckBox includeLocalCheckbox = new JCheckBox("Local", true);

    private SoundTrackerPlugin plugin;

    public SoundTrackerPanel(SoundTrackerPlugin plugin)
    {
        super(false);
        this.plugin = plugin;
        setLayout(new GridBagLayout());
        GridBagConstraints c = new GridBagConstraints();
        c.insets = new Insets(4, 4, 4, 4);
        int row = 0;

        //Title
        trackerTitleLabel.setHorizontalAlignment(SwingConstants.CENTER);
        trackerTitleLabel.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1),
                BorderFactory.createEmptyBorder(4, 4, 4, 4)));
        c.fill = GridBagConstraints.HORIZONTAL;
        c.weightx = 1;
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(trackerTitleLabel, c);
        row++;

        //Sound tracking toggles
        JPanel trackFilterRow = new JPanel(new GridLayout(2, 1, 0, 4));
        trackFilterRow.setOpaque(false);
        trackAreaCheckbox.setFocusable(false);
        trackLocalCheckbox.setFocusable(false);
        trackFilterRow.add(trackAreaCheckbox);
        trackFilterRow.add(trackLocalCheckbox);
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(trackFilterRow, c);
        row++;

        //Start/Stop buttons
        c.fill = GridBagConstraints.HORIZONTAL;
        c.weightx = 1;
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 1;
        add(startTrackingButton, c);
        c.gridx = 1;
        add(stopTrackingButton, c);
        row++;

        //Sound label/Save sound
        currentSoundLabel.setHorizontalAlignment(SwingConstants.LEFT);
        fixLabelWidth(currentSoundLabel, "ID (000/000) : 00000");
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 1;
        add(currentSoundLabel, c);
        c.gridx = 1;
        add(saveSoundButton, c);
        row++;

        //Channel label/Remove sound
        channelLabel.setHorizontalAlignment(SwingConstants.LEFT);
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 1;
        add(channelLabel, c);
        c.gridx = 1;
        add(removeSoundButton, c);
        row++;

        //Replay buttons
        JPanel navRow = new JPanel(new GridLayout(1, 3, 4, 0));
        navRow.setOpaque(false);
        navRow.add(playPreviousButton);
        navRow.add(playCurrentButton);
        navRow.add(playNextButton);
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(navRow, c);
        row++;

        //Clear tracked
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(clearTrackedButton, c);
        row++;

        //Clear removed
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(clearRemovedButton, c);
        row++;

        //Clear saved
        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(clearSavedButton, c);
        row++;

        //Sound export
        JPanel exportPanel = new JPanel(new GridBagLayout());
        GridBagConstraints ec = new GridBagConstraints();
        ec.insets = new Insets(2, 0, 2, 4);
        ec.fill = GridBagConstraints.HORIZONTAL;

        ec.gridx = 0;
        ec.gridy = 0;
        ec.gridwidth = 2;
        ec.weightx = 1;
        soundExportLabel.setHorizontalAlignment(SwingConstants.CENTER);
        soundExportLabel.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1),
                BorderFactory.createEmptyBorder(4, 4, 4, 4)));
        exportPanel.add(soundExportLabel, ec);

        ec.gridy = 1;
        ec.gridwidth = 2;
        ec.weightx = 1;
        exportPanel.add(includeAreaCheckbox, ec);

        ec.gridy = 2;
        ec.gridx = 0;
        ec.gridwidth = 1;
        ec.weightx = 0;
        exportPanel.add(includeLocalCheckbox, ec);

        ec.gridx = 1;
        ec.weightx = 1;
        exportPanel.add(exportSavedButton, ec);

        c.gridy = row;
        c.gridx = 0;
        c.gridwidth = 2;
        add(exportPanel, c);

        startTrackingButton.addActionListener(e -> onStartTracking());
        stopTrackingButton.addActionListener(e -> onStopTracking());
        playCurrentButton.addActionListener(e -> onPlayCurrentSound());
        playNextButton.addActionListener(e -> onPlayNextSound());
        playPreviousButton.addActionListener(e -> onPlayPreviousSound());
        saveSoundButton.addActionListener(e -> onSaveSound());
        removeSoundButton.addActionListener(e -> onRemoveSound());
        exportSavedButton.addActionListener(e -> onExportSounds());
        clearTrackedButton.addActionListener(e -> onClearTrackedSounds());
        clearRemovedButton.addActionListener(e -> onClearRemovedSounds());
        clearSavedButton.addActionListener(e -> onClearSavedSounds());

        includeAreaCheckbox.addActionListener(e -> updateSavedButtons());
        includeLocalCheckbox.addActionListener(e -> updateSavedButtons());

        updateTrackingButtons();
        updateClearButtons();
    }

    private void onStartTracking()
    {
        plugin.StartTracking();
        updateTrackingButtons();
    }

    private void onStopTracking()
    {
        plugin.StopTracking();
        updateTrackingButtons();
    }

    private void onPlayCurrentSound()
    {
        plugin.PlaySound(0);
    }

    private void onPlayNextSound()
    {
        plugin.PlaySound(1);
    }

    private void onPlayPreviousSound()
    {
        plugin.PlaySound(-1);
    }

    private void onSaveSound()
    {
        plugin.SaveSound();
        updateClearButtons();
        saveSoundButton.setEnabled(false);
    }

    private void onRemoveSound()
    {
        plugin.RemoveSound();
        updateClearButtons();
    }

    private void onClearTrackedSounds()
    {
        plugin.allSoundsList.clear();
        plugin.allSounds.clear();
        plugin.areaSounds.clear();
        plugin.localSounds.clear();
        plugin.indexInList = 0;
        clearSoundLabels();
        updateClearButtons();
    }

    private void onClearRemovedSounds()
    {
        plugin.removedSounds.clear();
        clearRemovedButton.setEnabled(false);
        trackerTitleLabel.requestFocusInWindow();
    }

    private void onClearSavedSounds()
    {
        plugin.savedLocalSounds.clear();
        plugin.savedAreaSounds.clear();
        clearSavedButton.setEnabled(false);
        exportSavedButton.setEnabled(false);
        saveSoundButton.setEnabled(!plugin.allSounds.isEmpty());
        trackerTitleLabel.requestFocusInWindow();
    }

    /**
     * Locks labels preferred/minimum width to largest text we need to render
     */
    private void fixLabelWidth(JLabel label, String largestText)
    {
        FontMetrics fm = label.getFontMetrics(label.getFont());
        int width = fm.stringWidth(largestText);
        int height = label.getPreferredSize().height;
        Dimension d = new Dimension(width, height);
        label.setPreferredSize(d);
        label.setMinimumSize(d);
    }

    public void setCurrentSoundId(int soundId, boolean isAreaSound)
    {
        currentSoundLabel.setText("ID (" + (plugin.indexInList + 1) + "/" + plugin.allSounds.size() + "): " + soundId);
        setChannel(isAreaSound);
        saveSoundButton.setEnabled(!plugin.savedAreaSounds.contains(soundId) && !plugin.savedLocalSounds.contains(soundId));
        removeSoundButton.setEnabled(true);
    }

    public void clearSoundLabels()
    {
        currentSoundLabel.setText("ID (0/0): -");
        channelLabel.setText("Channel: -");
        saveSoundButton.setEnabled(false);
        removeSoundButton.setEnabled(false);
    }

    public void setChannel(boolean isAreaSound)
    {
        String display = isAreaSound? "Area" : "Local";
        channelLabel.setText("Channel: " + display);
    }

    /**
     * Enables/disables the start and stop buttons
     */
    public void updateTrackingButtons()
    {
        startTrackingButton.setEnabled(!plugin.tracking);
        stopTrackingButton.setEnabled(plugin.tracking);

        // Switch focus between start/stop
        if (plugin.tracking)
        {
            stopTrackingButton.requestFocusInWindow();
        }
        else
        {
            startTrackingButton.requestFocusInWindow();
        }
    }

    public void updateClearButtons(){
        clearRemovedButton.setEnabled(!plugin.removedSounds.isEmpty());
        clearTrackedButton.setEnabled(!plugin.allSounds.isEmpty());

        updateSavedButtons();
        trackerTitleLabel.requestFocusInWindow();
    }

    public void updateSavedButtons(){
        boolean hasAreaSounds = !plugin.savedAreaSounds.isEmpty();
        boolean hasLocalSounds = !plugin.savedLocalSounds.isEmpty();
        clearSavedButton.setEnabled(hasAreaSounds || hasLocalSounds);

        boolean exportable = (hasAreaSounds && includeAreaCheckbox.isSelected())
                          || (hasLocalSounds && includeLocalCheckbox.isSelected());
        exportSavedButton.setEnabled(exportable);
    }


    public void enableTrackedButton(){
        clearTrackedButton.setEnabled(true);
    }


    /**
     * Copies saved sound ids to the clipboard, separated by commas.
     */
    private void onExportSounds()
    {
        boolean trackArea = includeAreaCheckbox.isSelected();
        boolean trackLocal = includeLocalCheckbox.isSelected();

        if (!trackArea && !trackLocal)
        {
            return;
        }

        Stream<Integer> stream = Stream.empty();

        if (trackArea)
        {
            stream = Stream.concat(stream, plugin.savedAreaSounds.stream());
        }
        if (trackLocal)
        {
            stream = Stream.concat(stream, plugin.savedLocalSounds.stream());
        }

        String joined = stream
                .map(String::valueOf)
                .collect(java.util.stream.Collectors.joining(","));
        StringSelection selection = new StringSelection(joined);
        Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
        clipboard.setContents(selection, null);
    }

    public boolean trackingAreaSounds(){
        return trackAreaCheckbox.isSelected();
    }

    public boolean trackingLocalSounds(){
        return trackLocalCheckbox.isSelected();
    }
}

package com.soundtracker;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.AreaSoundEffectPlayed;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Slf4j
@PluginDescriptor(
		name = "Sound Tracker",
		description = "Track unique sound effects, used in other plugins (ex: annoyance mute)"
)
public class SoundTrackerPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ClientThread clientThread;

	SoundTrackerPanel soundTrackerPanel;

	private NavigationButton navButton;

	public boolean tracking = false;
	public Set<Integer> allSounds = new HashSet<>();
	public List<Integer> allSoundsList = new ArrayList<>();
	public Set<Integer> areaSounds = new HashSet<>();
	public Set<Integer> localSounds = new HashSet<>();
	public Set<Integer> removedSounds = new HashSet<>();

	public List<Integer> savedAreaSounds =  new ArrayList<>();
	public List<Integer> savedLocalSounds =  new ArrayList<>();

	int indexInList = 0;


	@Override
	protected void startUp() throws Exception
	{
		soundTrackerPanel = new SoundTrackerPanel(this);

		final BufferedImage icon_panel = ImageUtil.loadImageResource(getClass(), "icon_Panel.png");
		navButton = NavigationButton.builder()
				.tooltip("Sound Tracker")
				.icon(icon_panel)
				.panel(soundTrackerPanel)
				.build();

		clientToolbar.addNavigation(navButton);

		allSounds = new HashSet<>();
		allSoundsList = new ArrayList<>();
		areaSounds = new HashSet<>();
		localSounds = new HashSet<>();
		savedAreaSounds = new ArrayList<>();
		savedLocalSounds = new ArrayList<>();

		indexInList = 0;
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
	}

	public void PlaySound(int diff){
		if(allSoundsList.isEmpty())
			return;
		clientThread.invokeLater(() -> {
			indexInList += diff;
			if(indexInList > (allSounds.size() - 1)){
				indexInList = 0;
			}
			if(indexInList < 0){
				indexInList = allSounds.isEmpty() ? 0 : (allSounds.size() - 1);
			}
			updateSoundIdText();
			int sound = allSoundsList.get(indexInList);
			client.playSoundEffect(sound);
		});
	}

	public void RemoveSound(){
		if(allSoundsList.isEmpty())
			return;

		int sound = allSoundsList.get(indexInList);
		removedSounds.add(sound);
		allSoundsList.remove(indexInList);
		allSounds.remove(sound);
		areaSounds.remove(sound);
		localSounds.remove(sound);

		int lastIndex = allSounds.isEmpty() ? 0 : (allSounds.size() - 1);

		if(indexInList > lastIndex){
			indexInList = lastIndex;
		}

		if(!allSoundsList.isEmpty())
		{
			updateSoundIdText();
			PlaySound(0);
		}else{
			soundTrackerPanel.clearSoundLabels();
		}
	}

	public void updateSoundIdText(){
		int sound = allSoundsList.get(indexInList);
		boolean isAreaSound = areaSounds.contains(sound);
		soundTrackerPanel.setCurrentSoundId(sound, isAreaSound);
	}


	public void SaveSound(){
		if(allSoundsList.isEmpty())
			return;

		int sound = allSoundsList.get(indexInList);
		boolean isAreaSound = areaSounds.contains(sound);

		if(isAreaSound){
			if(!savedAreaSounds.contains(sound)){
				savedAreaSounds.add(sound);
			}
		}else{
			if(!savedLocalSounds.contains(sound)){
				savedLocalSounds.add(sound);
			}
		}
	}

	public void StartTracking(){
		tracking = true;
	}

	public void StopTracking(){
		tracking = false;
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed soundEffectPlayed)
	{
		if(!tracking)
			return;
		if(!soundTrackerPanel.trackingLocalSounds())
			return;
		int sound = soundEffectPlayed.getSoundId();
		if(removedSounds.contains(sound))
			return;

		TrackSound(sound,false);
	}

	@Subscribe
	public void onAreaSoundEffectPlayed(AreaSoundEffectPlayed areaSoundEffectPlayed)
	{
		if(!tracking)
			return;
		if(!soundTrackerPanel.trackingAreaSounds())
			return;
		int sound = areaSoundEffectPlayed.getSoundId();
		if(removedSounds.contains(sound))
			return;

		TrackSound(sound,true);
	}

	void TrackSound(int sound, boolean area){
		boolean wasEmpty = allSounds.isEmpty();

		if(allSounds.add(sound))
		{
			if(area){
				areaSounds.add(sound);
			}else{
				localSounds.add(sound);
			}
			allSoundsList.add(sound);
			if(wasEmpty){
				soundTrackerPanel.enableTrackedButton();
			}
			updateSoundIdText();
		}
	}
}

package com.soundtracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SoundTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SoundTrackerPlugin.class);
		RuneLite.main(args);
	}
}
